# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">ORUÇ VE ZEKÂT İBADETLERİNE GİRİŞ (TDB.1.2)</text>\n  <rect x="20" y="48" width="320" height="192" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="180" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Oruç İbadeti (Bedenî İbadet)</text>\n  <text x="38" y="98" font-size="11.5" fill="#1e3a8a">• Tanım: İmsak vaktinden iftar vaktine kadar</text>\n  <text x="38" y="116" font-size="11.5" fill="#1e3a8a">ibadet niyetiyle yeme ve içmeden uzak durmaktır.</text>\n  <text x="38" y="140" font-size="11.5" fill="#1e3a8a">• Farz Oruç: Ramazan ayı orucu (ve kazası).</text>\n  <text x="38" y="162" font-size="11.5" fill="#1e3a8a">• Vacip Oruç: Adak orucu, bozulan nafilenin kazası.</text>\n  <text x="38" y="184" font-size="11.5" fill="#1e3a8a">• Nafile Oruç: Aşure, Şevval, Pazartesi-Perşembe.</text>\n  <text x="180" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#2563eb">Rükünleri: Niyet ve İmsak (Uzak Durmak)</text>\n\n  <rect x="360" y="48" width="320" height="192" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="520" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Zekât İbadeti (Malî İbadet)</text>\n  <text x="378" y="98" font-size="11.5" fill="#14532d">• Tanım: Nisap miktarı mala sahip zengin Müslümanın</text>\n  <text x="378" y="116" font-size="11.5" fill="#14532d">yılda bir kez malının belirli payını yoksula vermesidir.</text>\n  <text x="378" y="140" font-size="11.5" fill="#14532d">• Nisap: Temel ihtiyaçlar dışında 85 g altın (veya</text>\n  <text x="378" y="158" font-size="11.5" fill="#14532d">değeri para/ticaret malı) ölçüsündeki zenginlik sınırıdır.</text>\n  <text x="378" y="182" font-size="11.5" fill="#14532d">• Oran: Altın, para ve ticaret malında 1/40 (%2,5).</text>\n  <text x="520" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">Verileceği Yerler: Tevbe Suresi 60. Ayet (8 Sınıf)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">NAMAZ, ORUÇ VE ZEKÂTIN BİREYSEL VE TOPLUMSAL HİKMETLERİ</text>\n  <rect x="20" y="48" width="210" height="192" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="125" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#a16207">Namazın Hikmetleri</text>\n  <text x="32" y="98" font-size="11.5" fill="#713f12">• Günde 5 kez Allah\'ın huzuruna</text>\n  <text x="32" y="116" font-size="11.5" fill="#713f12">çıkarak manevi huzur verir.</text>\n  <text x="32" y="140" font-size="11.5" fill="#713f12">• Zamanı planlama bilinci ve</text>\n  <text x="32" y="158" font-size="11.5" fill="#713f12">abdestle temizlik alışkanlığı katar.</text>\n  <text x="32" y="182" font-size="11.5" fill="#713f12">• Cemaatle namaz omuz omuza</text>\n  <text x="32" y="200" font-size="11.5" fill="#713f12">eşitlik ve kardeşlik sağlar.</text>\n  <text x="125" y="224" text-anchor="middle" font-size="11" font-weight="bold" fill="#854d0e">Kötülüklerden Alıkoyar (Ankebût 45)</text>\n\n  <rect x="245" y="48" width="210" height="192" rx="8" fill="#fdf2f8" stroke="#ec4899" stroke-width="1.5"/>\n  <text x="350" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#be185d">Orucun Hikmetleri</text>\n  <text x="257" y="98" font-size="11.5" fill="#831843">• İradeyi terbiye eder, sabır ve</text>\n  <text x="257" y="116" font-size="11.5" fill="#831843">öz denetim gücünü artırır.</text>\n  <text x="257" y="140" font-size="11.5" fill="#831843">• Nimetlerin kıymetini öğreterek</text>\n  <text x="257" y="158" font-size="11.5" fill="#831843">şükür ve kanaat duygusu verir.</text>\n  <text x="257" y="182" font-size="11.5" fill="#831843">• Açların hâlini hissettirerek</text>\n  <text x="257" y="200" font-size="11.5" fill="#831843">empati ve merhameti geliştirir.</text>\n  <text x="350" y="224" text-anchor="middle" font-size="11" font-weight="bold" fill="#9d174d">Ahlaki Arınma ve Kalkan</text>\n\n  <rect x="470" y="48" width="210" height="192" rx="8" fill="#faf5ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="575" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#7e22ce">Zekât ve Sadakanın Hikmeti</text>\n  <text x="482" y="98" font-size="11.5" fill="#581c87">• İnsanı cimrilik, bencillik ve</text>\n  <text x="482" y="116" font-size="11.5" fill="#581c87">mal hırsından temizler.</text>\n  <text x="482" y="140" font-size="11.5" fill="#581c87">• Malı temizler ve bereketlendirir.</text>\n  <text x="482" y="164" font-size="11.5" fill="#581c87">• Zengin ile yoksul arasındaki</text>\n  <text x="482" y="182" font-size="11.5" fill="#581c87">farkı azaltır, kıskançlığı önler,</text>\n  <text x="482" y="200" font-size="11.5" fill="#581c87">toplumsal barışı güçlendirir.</text>\n  <text x="575" y="224" text-anchor="middle" font-size="11" font-weight="bold" fill="#6b21a8">Sosyal Adalet ve Dayanışma</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">2. ÜNİTE DEĞERLENDİRMESİ: İSLAM VE İBADET ÖZET ŞEMASI</text>\n  <rect x="25" y="48" width="650" height="92" rx="8" fill="#ecfeff" stroke="#06b6d4" stroke-width="1.5"/>\n  <text x="350" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#0e7490">İbadetlerin Kabul Şartları, Türleri ve Mükellefiyet</text>\n  <text x="350" y="98" text-anchor="middle" font-size="12" fill="#155e75">• Mükellef: Akıllı ve ergenlik çağına ulaşmış Müslüman · Kabul Şartı: İman, İhlas (samimiyet) ve Sünnete Uygunluk.</text>\n  <text x="350" y="122" text-anchor="middle" font-size="12" fill="#155e75">• Türleri: 1. Bedenî (Namaz, Oruç) · 2. Malî (Zekât, Fitre) · 3. Hem Bedenî Hem Malî (Hac).</text>\n\n  <rect x="25" y="152" width="650" height="90" rx="8" fill="#fff7ed" stroke="#f97316" stroke-width="1.5"/>\n  <text x="350" y="176" text-anchor="middle" font-size="13" font-weight="bold" fill="#c2410c">Temizlik (Tahâret) ve Namazın 12 Farzı</text>\n  <text x="350" y="202" text-anchor="middle" font-size="12" fill="#9a3412">• Abdestin 4 Farzı (Yüz, kollar, başın meshi, ayaklar) · Guslün 3 Farzı (Ağız, burun, tüm beden) · Teyemmümün 2 Farzı.</text>\n  <text x="350" y="226" text-anchor="middle" font-size="12" fill="#9a3412">• Namazın Dışındaki 6 Şart (Hadesten/Necasetten taharet, Setr-i avret, İstikbal-i kıble, Vakit, Niyet) + İçindeki 6 Rükün.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
